<?php
namespace Azuriom\Plugin\GamingHubCore\Services;
use Azuriom\Plugin\GamingHubCore\Data\{NormalizedRegistry,RegistryExtension}; use Azuriom\Plugin\GamingHubCore\Exceptions\InvalidExtensionRegistry;
final class ExtensionRegistryValidator { public function __construct(private ExtensionUrlGuard $urls){} public function validate(array $r,bool $official=false,bool $allowPrivate=false):NormalizedRegistry { if(($r['schema']??null)!==1)throw new InvalidExtensionRegistry('Unsupported registry schema.');$id=$this->id($r['id']??null);$name=$this->text($r['name']??null,150,'registry name');$home=isset($r['homepage'])?$this->url($r['homepage'],$allowPrivate):null;$seen=[];$items=[];foreach(($r['extensions']??[]) as $e){if(!is_array($e))throw new InvalidExtensionRegistry('Invalid extension entry.');$eid=$this->id($e['id']??null);if(isset($seen[$eid]))throw new InvalidExtensionRegistry('Duplicate extension ID: '.$eid);$seen[$eid]=true;$repo=$this->url($e['repository']??null,$allowPrivate);$ver=(string)($e['latest_version']??'');if(!preg_match('/^v?\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/',$ver))throw new InvalidExtensionRegistry('Invalid semantic version for '.$eid);$asset=$this->text($e['release_asset']??null,255,'release asset');if(!str_ends_with(strtolower(str_replace('*','x',$asset)),'.zip'))throw new InvalidExtensionRegistry('Release asset must target ZIP packages.');$items[]=new RegistryExtension($eid,$this->text($e['name']??null,150,'name'),$this->text($e['description']??'',1000,'description'),$this->text($e['author']??'',150,'author'),$this->text($e['category']??'Other',80,'category'),$repo,$asset,isset($e['checksum_asset'])?$this->text($e['checksum_asset'],255,'checksum asset'):null,ltrim($ver,'v'),(bool)($e['verified']??false),$official&&(bool)($e['official']??false),isset($e['icon'])?$this->url($e['icon'],$allowPrivate):null,isset($e['release_notes_url'])?$this->url($e['release_notes_url'],$allowPrivate):null,$e); } return new NormalizedRegistry(1,$id,$name,$home,$items,now()->toIso8601String()); }
 private function id(mixed $v):string{$v=(string)$v;if(!preg_match('/^[a-z0-9][a-z0-9-]{1,98}[a-z0-9]$/',$v))throw new InvalidExtensionRegistry('Invalid ID.');return $v;} private function text(mixed $v,int $max,string $field):string{$v=trim((string)$v);if(mb_strlen($v)>$max||preg_match('/<[^>]+>/',$v))throw new InvalidExtensionRegistry('Invalid '.$field.'.');return $v;} private function url(mixed $v,bool $allow):string{$v=(string)$v;$this->urls->assertSafe($v,$allow);return $v;}
}
